async def verify(self) -> UnionCompositionResult:
    """Return an observation only while its participant roster remains current."""
    roster = await self._roster()

    async def validate_roster() -> None:
        if await self._roster() != roster:
            raise UnionHeadReadError(
                scope_key=self._scope.key,
                branch=None,
                reason="the scope union roster changed during verification",
            )

    return await self._tick.verify(
        lane_branches=roster, validate_roster=validate_roster
    )

async def _read_scope_facts(
    *, ref: ScopeRef, tracker: TrackerPort
) -> tuple[ScopePlanSnapshot, tuple[TrackerIssue, ...]]:
    """Share the same native observations and rereads across scope consumers."""
    tracker.require_scope_plan_reads()
    members = await read_scope_members(tracker=tracker, scope=ref)
    for key, issue in members.items():
        if await tracker.read_planning_issue(issue_key=key) != issue:
            raise ScopeReadError(f"scope fact changed during planning: {key}", ref=ref)
    subtree = await read_member_subtrees(tracker=tracker, scope=ref, members=members)
    for key, issue in subtree.items():
        if key in members:
            continue
        if await tracker.read_planning_issue(issue_key=key) != issue:
            raise ScopeReadError(
                f"subtree fact changed during planning: {key}", ref=ref
            )
    facts = dict(members)
    pending = list(members.values())
    while pending:
        issue = pending.pop()
        for key in blocker_keys(issue):
            if key in facts:
                continue
            dependency = await tracker.read_planning_issue(issue_key=key)
            if dependency.issue_key != key:
                raise ScopeReadError(
                    "dependency read changed the requested identity", ref=ref
                )
            facts[key] = dependency
            pending.append(dependency)
    # Check the native observations again before either a refusal or a plan.
    # A missing or moved dependency is never interpreted as a closed blocker.
    for key, issue in facts.items():
        if await tracker.read_planning_issue(issue_key=key) != issue:
            raise ScopeReadError(f"dependency changed during planning: {key}", ref=ref)
    if await read_scope_members(tracker=tracker, scope=ref) != members:
        raise ScopeReadError("scope family changed during planning", ref=ref)
    if (
        await read_member_subtrees(tracker=tracker, scope=ref, members=members)
        != subtree
    ):
        raise ScopeReadError("member subtrees changed during planning", ref=ref)
    snapshot = ScopePlanSnapshot(
        scope=ResolvedScope(ref=ref, issues=tuple(members.values())),
        dependencies=tuple(issue for key, issue in facts.items() if key not in members),
    )
    return snapshot, tuple(subtree.values())

async def _fetch(self) -> None:
    try:
        await settle(self._git.fetch(self._context.repo_path))
    except (OSError, RuntimeError, ValueError) as exc:
        raise UnionHeadReadError(
            scope_key=self._context.scope_key,
            branch=None,
            reason="the configured remote could not be fetched",
        ) from exc

async def _read_heads(self, plan: UnionTickPlan) -> tuple[UnionLaneHead, ...]:
    observed: list[UnionLaneHead] = []
    for lane in plan.lanes:
        try:
            sha = await read_remote_head(
                git=self._git,
                repository=self._context.repo_path,
                remote=self._context.git_remote,
                branch=lane.branch,
            )
            if sha is None:
                raise UnionHeadReadError(
                    scope_key=self._context.scope_key,
                    branch=lane.branch,
                    reason="the planned branch is absent on the remote",
                )
            observed.append(
                UnionLaneHead(
                    lane_key=lane.lane_key, branch=lane.branch, head_sha=sha
                )
            )
        except (OSError, RuntimeError, ValueError) as exc:
            raise UnionHeadReadError(
                scope_key=self._context.scope_key,
                branch=lane.branch,
                reason="the planned branch has no readable commit identity",
            ) from exc
    await require_union_object_identity(
        git=self._git,
        repository=self._context.repo_path,
        scope_key=self._context.scope_key,
    )
    return tuple(observed)

RANKING: dict[str, IssuePriority] = {
    "a": IssuePriority.LOW,
    "z": IssuePriority.URGENT,
}

def work_ref(lane: str, branch: str, sha: str) -> WorkRef:
    return WorkRef(
        issue_id=lane,
        role=WorkRefRole.DELIVERABLE,
        branch=branch,
        pushed_head_sha=sha,
        recorded_at=datetime(2026, 1, 1, tzinfo=UTC),
    )

def __init__(self, heads: tuple[object, ...]) -> None:
    self.by_lane = {head.lane_key: head for head in heads}
    self.refs: dict[str, list[WorkRef]] = {
        lane: [
            work_ref(lane, self.by_lane[lane].branch, self.by_lane[lane].head_sha)
        ]
        for lane in OPENED_ORDER
    }
    self.rows = [
        row
        for lane in OPENED_ORDER
        for row in (
            issue(lane, priority=RANKING[lane]),
            issue(
                f"{lane}-check",
                parent_key=lane,
                issue_labels=frozenset({"criterion"}),
            ),
        )
    ]

def close_every_criterion(self) -> None:
    for lane in OPENED_ORDER:
        key = f"{lane}-check"
        index = next(i for i, row in enumerate(self.rows) if row.issue_key == key)
        self.rows[index] = self.rows[index].model_copy(
            update={
                "state_name": "Done",
                "state_kind": WorkflowStateKind.COMPLETED,
            }
        )

def tracker(self) -> FakeTrackerPort:
    return FakeTrackerPort(
        issues=self.rows,
        scope_containers=[
            ScopeContainer(
                ref=PROJECT,
                name=PROJECT.key,
                description=f"Complete description of {PROJECT.key}",
                url=f"https://tracker.invalid/project/{PROJECT.key}",
                parent=None,
            )
        ],
        scope_memberships={PROJECT: list(OPENED_ORDER)},
        scope_label_members={PROJECT: frozenset({ScopeLabel.APPROVED})},
        recorded_work_refs=self.refs,
    )

@pytest.mark.parametrize("changed", ["membership", "reference"])
async def test_roster_change_during_measurement_refuses_before_return(
    delivery, changed
):
    class MovingRosterRunner(SubprocessCheckChainRunner):
        async def run_chain(self, *, cwd, steps):
            result = await super().run_chain(cwd=cwd, steps=steps)
            if changed == "membership":
                delivery.tracker.scope_memberships[PROJECT] = ("z",)
            else:
                delivery.tracker.recorded_work_refs["z"] = [
                    work_ref("z", "work/a", delivery.sha("a"))
                ]
            return result

    runner = MovingRosterRunner(timeout=AppConfig().union_check_step_timeout_seconds)
    with pytest.raises(UnionHeadReadError, match="roster changed"):
        await delivery.coordinator(runner).verify()
    assert delivery.git.created == delivery.git.removed
    assert all(not Path(path).exists() for path in delivery.git.created)

async def test_cyclic_parentage_is_refused_before_any_union_work(delivery):
    from kodezart.domain.errors import ScopeReadError

    for lane, parent in (("a", "z"), ("z", "a")):
        delivery.tracker.issues[lane] = delivery.tracker.issues[lane].model_copy(
            update={"parent_key": parent}
        )
    with pytest.raises(ScopeReadError):
        await delivery.coordinator().verify()
    assert delivery.git.created == []

async def test_dependency_cycle_is_refused_before_any_union_work(delivery):
    from kodezart.domain.errors import ScopeCycleError
    from kodezart.types.domain.tracker import IssueRelation, IssueRelationKind

    for lane, blocker in (("a", "z"), ("z", "a")):
        delivery.tracker.issues[lane] = delivery.tracker.issues[lane].model_copy(
            update={
                "relations": (
                    IssueRelation(kind=IssueRelationKind.BLOCKED_BY, issue_key=blocker),
                )
            }
        )
    with pytest.raises(ScopeCycleError):
        await delivery.coordinator().verify()
    assert delivery.git.created == []

async def test_missing_dependency_is_not_dropped_by_empty_blocking_predicate(delivery):
    from kodezart.types.domain.tracker import IssueRelation, IssueRelationKind

    delivery.tracker.issues["a"] = delivery.tracker.issues["a"].model_copy(
        update={
            "relations": (
                IssueRelation(kind=IssueRelationKind.BLOCKED_BY, issue_key="absent"),
            )
        }
    )
    with pytest.raises(KeyError, match="absent"):
        await delivery.coordinator().verify()
    assert delivery.git.created == []

