def with_checks(self, checks: object) -> None:
    """Replace the declared chain on the repository this scope composes."""
    self.context = self.context.model_copy(
        update={"repo": self.context.repo.model_copy(update={"checks": checks})}
    )

async def refs(self) -> tuple[str, ...]:
    """Every ref in every repository — what any publication would move."""
    return tuple(
        [
            await pinned.git(path, "show-ref")
            for path in (self.author, self.remote, self.observer)
        ]
    )

@pytest.mark.parametrize("barrier", ["none", "open-decision", "backlog-criterion"])
async def test_retained_union_is_observable_under_future_stage_barrier(
    tmp_path, barrier
):
    fixture = await build_delivery(tmp_path / "world")
    if barrier == "open-decision":
        decision = issue("decision-record", issue_labels=frozenset({"decision"}))
        fixture.tracker.issues[decision.issue_key] = decision
        fixture.tracker.scope_memberships[PROJECT] = ("a", "z", decision.issue_key)
    elif barrier == "backlog-criterion":
        fixture.tracker.issues["a-check"] = fixture.tracker.issues[
            "a-check"
        ].model_copy(
            update={"state_kind": WorkflowStateKind.BACKLOG, "state_name": "Backlog"}
        )

    result = await fixture.coordinator().verify()

    assert result.composition_order == ("z", "a")
    assert result.outcome is UnionOutcome.GREEN
    assert fixture.git.created == fixture.git.removed == [result.scratch_path]

def deliverable(key, *, parent=None):
    """A deliverable issue: a candidate the walk may select, never a record."""
    return make_tracker_issue(key, parent_key=parent, project_id=PROJECT.key)

def board(*issues, members):
    """A project carrying exactly *members*; every other issue is below them."""
    return FakeTrackerPort(
        issues=issues,
        scope_containers=[
            ScopeContainer(
                ref=PROJECT,
                name="fixture project",
                description="",
                url="https://tracker.invalid/p",
            ),
        ],
        scope_memberships={PROJECT: list(members)},
        scope_label_members={PROJECT: frozenset({ScopeLabel.APPROVED})},
    )

def nested_board(*, deep_state, deep_labels=CRITERION):
    """One member, a deliverable child the filter misses, and its own record."""
    return board(
        deliverable("root"),
        record("root-check", parent="root", labels=CRITERION),
        deliverable("child", parent="root"),
        record(
            "child-record", parent="child", labels=deep_labels, state_kind=deep_state
        ),
        members=("root",),
    )

@pytest.mark.parametrize(
    "labels,state_kind",
    [
        (CRITERION, WorkflowStateKind.UNSTARTED),
        (DECISION, WorkflowStateKind.COMPLETED),
        (DECISION, WorkflowStateKind.CANCELED),
    ],
)
async def test_a_subtree_that_offends_nothing_returns_the_filtered_family(
    labels, state_kind
):
    """Reading the subtree widens the barrier, never the scope's membership."""
    tracker = nested_board(deep_state=state_kind, deep_labels=labels)
    plan = await read_scope_plan(ref=PROJECT, tracker=tracker)
    assert {issue.issue_key for issue in plan.scope.issues} == {"root", "root-check"}
    assert plan.dependencies == ()

def __init__(self):
    self.actual = SubprocessCheckChainRunner(
        timeout=AppConfig().union_check_step_timeout_seconds
    )
    self.calls = []
    self.after = None

@property
def branches(self):
    return tuple(
        UnionLaneBranch(lane_key=h.lane_key, branch=h.branch) for h in self.heads
    )

def consumer(self, attempts=3, context=None):
    return UnionTick(
        composition=UnionComposition(
            git=self.git,
            runner=self.runner,
            author_name="Fixture",
            author_email="fixture@example.invalid",
        ),
        git=self.git,
        context=context or self.context,
        config=AppConfig(union_stale_max_attempts=attempts),
    )

